def generate(rng):
    above = [rng.randint(301, 650) for _ in range(rng.randint(2, 4))]
    rest = [rng.randint(90, 299) for _ in range(6 - len(above))]
    week = above + rest + [300]
    rng.shuffle(week)
    return {'week': week}

